scripts.script:
local pet_amount = 10 --Change to whatever, this game has no trading though

function random_number_string(n)
    local t = {}
    for i = 1, n do
        t[i] = math.random(0, 9)
    end
    return table.concat(t, "")
end

local args = {
    [1] = {
        [1] = "Pro Lebron",
        [2] = false,
        [3] = "Huge",
        [4] = ""
    },
    [2] = "Pets"
}

function give_pet()
    args[1][4] = random_number_string(16)
    game:GetService("ReplicatedStorage"):WaitForChild("Events"):WaitForChild("AddValueToTable"):FireServer(unpack(args))
end

for i=1, pet_amount do
    give_pet()
    task.wait()
end
